from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final[Path] = Path("notes")


def _resolve_note(name: str) -> Path | None:
    """Return the path of `name` inside NOTES_DIR, or None if it is rejected.

    Rejects absolute paths, names with '..' that climb out of NOTES_DIR,
    names containing NUL bytes, and symlinks that resolve outside NOTES_DIR.
    Does not check whether the path is a readable regular file.
    """
    if "\x00" in name or Path(name).is_absolute():
        return None
    base = NOTES_DIR.resolve()
    try:
        candidate = (base / name).resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if not candidate.is_relative_to(base):
        return None
    return candidate


def count_readable(names: list[str]) -> int:
    """Count entries of `names` that are readable regular files inside NOTES_DIR.

    Each entry is counted separately, so duplicates count again. Missing or
    unreadable files contribute nothing. No name may cause a read outside
    NOTES_DIR.
    """
    count = 0
    for name in names:
        path = _resolve_note(name)
        if path is None or not path.is_file():
            continue
        try:
            with path.open("rb"):
                pass
        except OSError:
            continue
        count += 1
    return count


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / "notes"
    d.mkdir()
    (d / "a.txt").write_text("hello")
    (d / "empty.txt").write_text("")
    (d / "sub").mkdir()
    (tmp_path / "secret.txt").write_text("top secret")
    return d


def test_counts_only_readable_files(notes: Path) -> None:
    assert count_readable(["a.txt", "empty.txt", "missing.txt"]) == 2


def test_empty_name_list(notes: Path) -> None:
    assert count_readable([]) == 0


def test_duplicates_count_each_entry(notes: Path) -> None:
    assert count_readable(["a.txt", "a.txt"]) == 2


def test_directory_is_not_a_file(notes: Path) -> None:
    assert count_readable(["sub"]) == 0


def test_parent_traversal_rejected(notes: Path) -> None:
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0


def test_absolute_path_outside_rejected(notes: Path, tmp_path: Path) -> None:
    assert count_readable([str(tmp_path / "secret.txt")]) == 0


def test_nul_byte_rejected(notes: Path) -> None:
    assert count_readable(["a.txt\x00"]) == 0


def test_symlink_escaping_notes_rejected(notes: Path, tmp_path: Path) -> None:
    (notes / "link").symlink_to(tmp_path / "secret.txt")
    assert count_readable(["link"]) == 0


def test_resolve_note_rejects_traversal(notes: Path) -> None:
    assert _resolve_note("../secret.txt") is None
